1. @page "/board"
2. @rendermode InteractiveServer
3. @inject ITaskService TaskService
4. 
5. <PageTitle>Kanban Board</PageTitle>
6. 
7. <h1>Kanban Board</h1>
8. 
9. @if (loading)
10. {
11.     <p class="loading-message">Loading tasks...</p>
12. }
13. else if (errorMessage is not null)
14. {
15.     <p class="error-message">@errorMessage</p>
16. }
17. else
18. {
19.     <BoardStatsBar Total="allTasks.Count"
20.                    TodoCount="todoTasks.Count"
21.                    InProgressCount="inProgressTasks.Count"
22.                    DoneCount="doneTasks.Count"
23.                    OverdueCount="overdueTasks.Count" />
24. 
25.     <div class="search-bar">
26.         <input type="text" placeholder="Search tasks by title..." @bind="searchText" @bind:event="oninput" />
27.     </div>
28. 
29.     <div class="kanban-board">
30.         <KanbanColumn ColumnName="@StatusTodo"
31.                       Tasks="filteredTodo"
32.                       ShowMoveLeft="false"
33.                       ShowMoveRight="true"
34.                       OnMoveRight="@(id => MoveTask(id, StatusInProgress))"
35.                       OnAddTask="@(data => AddTask(data, StatusTodo))" />
36. 
37.         <KanbanColumn ColumnName="@StatusInProgress"
38.                       Tasks="filteredInProgress"
39.                       ShowMoveLeft="true"
40.                       ShowMoveRight="true"
41.                       OnMoveLeft="@(id => MoveTask(id, StatusTodo))"
42.                       OnMoveRight="@(id => MoveTask(id, StatusDone))"
43.                       OnAddTask="@(data => AddTask(data, StatusInProgress))" />
44. 
45.         <KanbanColumn ColumnName="@StatusDone"
46.                       Tasks="filteredDone"
47.                       ShowMoveLeft="true"
48.                       ShowMoveRight="false"
49.                       OnMoveLeft="@(id => MoveTask(id, StatusInProgress))"
50.                       OnAddTask="@(data => AddTask(data, StatusDone))" />
51.     </div>
52. }
53. 
54. @code {
55.     private const string StatusTodo = "To Do";
56.     private const string StatusInProgress = "In Progress";
57.     private const string StatusDone = "Done";
58. 
59.     private List<TaskItem> allTasks = new();
60.     private bool loading = true;
61.     private string? errorMessage;
62.     private string searchText = string.Empty;
63. 
64.     private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == StatusTodo).ToList();
65.     private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == StatusInProgress).ToList();
66.     private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == StatusDone).ToList();
67.     private List<TaskItem> overdueTasks => allTasks.Where(t => t.DueDate < DateTime.Today && t.Status != StatusDone).ToList();
68. 
69.     private List<TaskItem> filteredTodo => Filter(todoTasks);
70.     private List<TaskItem> filteredInProgress => Filter(inProgressTasks);
71.     private List<TaskItem> filteredDone => Filter(doneTasks);
72. 
73.     private List<TaskItem> Filter(List<TaskItem> tasks)
74.     {
75.         if (string.IsNullOrWhiteSpace(searchText))
76.             return tasks;
77.         return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
78.     }
79. 
80.     protected override async Task OnInitializedAsync()
81.     {
82.         try
83.         {
84.             allTasks = await TaskService.GetAllTasksAsync();
85.         }
86.         catch (Exception ex)
87.         {
88.             errorMessage = $"Failed to load tasks: {ex.Message}";
89.         }
90.         finally
91.         {
92.             loading = false;
93.         }
94.     }
95. 
96.     private async Task MoveTask(int taskId, string newStatus)
97.     {
98.         try
99.         {
100.             await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
101.             var task = allTasks.First(t => t.Id == taskId);
102.             var index = allTasks.IndexOf(task);
103.             allTasks[index] = task with { Status = newStatus };
104.         }
105.         catch (Exception ex)
106.         {
107.             errorMessage = $"Failed to move task: {ex.Message}";
108.         }
109.     }
110. 
111.     private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
112.     {
113.         try
114.         {
115.             var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
116.             allTasks.Add(newTask with { Status = status });
117.         }
118.         catch (Exception ex)
119.         {
120.             errorMessage = $"Failed to add task: {ex.Message}";
121.         }
122.     }
123. }
124.

